      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Para evitar ocorrências similares em operações de offloading com etapas de pull in, o material recomenda revisar gestão de mudança, treinamento e instruções específicas de execução segura.",
          "trechos": [
            "E8bdfd69764b991ab:694:1386",
            "E8bdfd69764b991ab:1386:2082"
          ],
          "condicoes": [
            "aplicável ao contexto do incidente com sistema IHTP/QRF durante offloading",
            "relacionado a procedimentos de offloading e pull in da contratada"
          ],
          "limites": [
            "a fonte trata de mangote de offloading, não de riser de produção",
            "são lições aprendidas e recomendações, não critérios universais de projeto"
          ]
        },
        {
          "proposicao": "A recomendação inclui avaliar cenário de rompimento do mangote no HAZOP e verificar salvaguardas automáticas de bloqueio para situações de baixa e alta pressão, como parte da resposta a contingências e preservação da integridade.",
          "trechos": [
            "E8bdfd69764b991ab:1386:2082"
          ],
          "condicoes": [
            "quando houver sistema de offloading com risco de rompimento e possibilidade de atuação automática"
          ],
          "limites": [
            "a fonte não fornece parâmetros de atuação, limites de pressão ou lógica detalhada",
            "o escopo é o sistema de offloading do caso investigado"
          ]
        },
        {
          "proposicao": "Também se recomenda verificar intertravamento e bloqueio automático do sistema e reavaliar dispositivos de liberação rápida no lado do FPSO, vinculando integridade operacional a compatibilidade entre projeto e operação.",
          "trechos": [
            "E8bdfd69764b991ab:1386:2082",
            "E8bdfd69764b991ab:2082:2331"
          ],
          "condicoes": [
            "em unidades com sistemas de offloading e dispositivos de liberação rápida semelhantes"
          ],
          "limites": [
            "não há demonstração experimental de eficácia em todas as configurações",
            "não substitui análise específica de risco e de projeto"
          ]
        }
      ]
    },
    {
      "id": "E45f75c28184a0001",
